#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Point {
    long long x, y;

    bool operator<(const Point& other) const {
        return x != other.x ? x < other.x : y < other.y;
    }

    bool operator==(const Point& other) const {
        return x == other.x && y == other.y;
    }
};

__int128 cross(const Point& a, const Point& b, const Point& c) {
    return (__int128)(b.x - a.x) * (c.y - a.y)
         - (__int128)(b.y - a.y) * (c.x - a.x);
}

int signOf(__int128 value) {
    return (value > 0) - (value < 0);
}

vector<Point> convexHull(vector<Point> points) {
    sort(points.begin(), points.end());
    points.erase(unique(points.begin(), points.end()), points.end());

    if (points.size() <= 1) return points;

    vector<Point> hull(2 * points.size());
    int k = 0;

    for (const Point& p : points) {
        while (k >= 2 && cross(hull[k - 2], hull[k - 1], p) <= 0) --k;
        hull[k++] = p;
    }

    for (int i = (int)points.size() - 2, t = k + 1; i >= 0; --i) {
        while (k >= t && cross(hull[k - 2], hull[k - 1], points[i]) <= 0) --k;
        hull[k++] = points[i];
    }

    hull.resize(k - 1);
    return hull;
}

bool onSegment(const Point& a, const Point& b, const Point& p) {
    return cross(a, b, p) == 0 &&
           min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&
           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);
}

bool segmentsIntersect(const Point& a, const Point& b,
                       const Point& c, const Point& d) {
    int c1 = signOf(cross(a, b, c));
    int c2 = signOf(cross(a, b, d));
    int c3 = signOf(cross(c, d, a));
    int c4 = signOf(cross(c, d, b));

    if (c1 == 0 && onSegment(a, b, c)) return true;
    if (c2 == 0 && onSegment(a, b, d)) return true;
    if (c3 == 0 && onSegment(c, d, a)) return true;
    if (c4 == 0 && onSegment(c, d, b)) return true;

    return c1 != c2 && c3 != c4;
}

bool containsPoint(const vector<Point>& polygon, const Point& p) {
    int n = polygon.size();

    if (n == 1) return polygon[0] == p;
    if (n == 2) return onSegment(polygon[0], polygon[1], p);

    for (int i = 0; i < n; ++i) {
        if (cross(polygon[i], polygon[(i + 1) % n], p) < 0)
            return false;
    }
    return true;
}

bool polygonsIntersect(const vector<Point>& a, const vector<Point>& b) {
    int na = a.size(), nb = b.size();

    for (int i = 0; i < na; ++i) {
        Point a1 = a[i];
        Point a2 = a[(i + 1) % na];

        for (int j = 0; j < nb; ++j) {
            Point b1 = b[j];
            Point b2 = b[(j + 1) % nb];

            if (segmentsIntersect(a1, a2, b1, b2))
                return true;
        }
    }

    return containsPoint(a, b[0]) || containsPoint(b, a[0]);
}

