    vector<Point> first(4), second(4);

    for (Point& p : first) cin >> p.x >> p.y;
    for (Point& p : second) cin >> p.x >> p.y;

    first = convexHull(first);
    second = convexHull(second);

    cout << (polygonsIntersect(first, second) ? "YES\n" : "NO\n");
    return 0;
}

