bool onSegment(const Point& a, const Point& b, const Point& p) {
    return cross(a, b, p) == 0 &&
           min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&
           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);
}

bool segmentsIntersect(const Point& a, const Point& b,
                       const Point& c, const Point& d) {
    long long c1 = cross(a, b, c);
    long long c2 = cross(a, b, d);
    long long c3 = cross(c, d, a);
    long long c4 = cross(c, d, b);

    if (c1 == 0 && onSegment(a, b, c)) return true;
    if (c2 == 0 && onSegment(a, b, d)) return true;
    if (c3 == 0 && onSegment(c, d, a)) return true;
    if (c4 == 0 && onSegment(c, d, b)) return true;

    return ((c1 > 0) != (c2 > 0)) && ((c3 > 0) != (c4 > 0));
}

void orderPoints(vector<Point>& p) {
    long double cx = 0, cy = 0;
    for (const auto& q : p) {
        cx += q.x;
        cy += q.y;
    }
    cx /= p.size();
    cy /= p.size();

    sort(p.begin(), p.end(), [&](const Point& a, const Point& b) {
        return atan2((long double)a.y - cy, (long double)a.x - cx) <
               atan2((long double)b.y - cy, (long double)b.x - cx);
    });
}

bool inside(const vector<Point>& polygon, const Point& p) {
    bool positive = false, negative = false;

    for (int i = 0; i < 4; ++i) {
        long long value = cross(polygon[i], polygon[(i + 1) % 4], p);
        positive |= value > 0;
        negative |= value < 0;
    }

    return !(positive && negative);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Point> a(4), b(4);

    for (auto& p : a) cin >> p.x >> p.y;
    for (auto& p : b) cin >> p.x >> p.y;

    orderPoints(a);
    orderPoints(b);

    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            if (segmentsIntersect(a[i], a[(i + 1) % 4],
                                  b[j], b[(j + 1) % 4])) {
                cout << "YES\n";
                return 0;
            }
        }
    }

    if (inside(a, b[0]) || inside(b, a[0]))
        cout << "YES\n";
    else
        cout << "NO\n";

    return 0;
}

